function contractLimitNotes(config) {
  const out = { trade: [], freeCorps: [] };
  const t = (config && config.trade) || {};
  const perFaction = (Number(t.maxOpenOffersPerFaction) || 0)
    + (t.wtsEnabled === true ? Number(t.wtsMaxOpenPerFaction) || 0 : 0);
  if (perFaction > VENDOR_CONTRACT_LIMIT_CORP) {
    out.trade.push(`open offers per faction (${perFaction}) > ${VENDOR_CONTRACT_LIMIT_CORP} corporation contracts an `
      + "NPC CEO may hold (EveJS ConTooManyContractsMax) - offers over it end CONTRACT_LIMIT");
  }
  const heads = Math.max(1, Number(config && config.virtualCorps && config.virtualCorps.corpsPerFaction) || 1);
  const vcOn = Boolean(config && config.modules && config.modules.virtualCorps
    && config.modules.virtualCorps.enabled === true);
  if (t.virtualIssuers === true && vcOn && Math.ceil(perFaction / heads) > VENDOR_CONTRACT_LIMIT_CHARACTER) {
    out.trade.push(`open offers per virtual issuer (${perFaction} over ${heads} heads) > `
      + `${VENDOR_CONTRACT_LIMIT_CHARACTER} personal contract a character may hold (EveJS ConTooManyContractsMax) - `
      + "offers over it end CONTRACT_LIMIT");
  }
  const fc = config && config.freeCorps && config.freeCorps.contracts;
  if (fc && fc.enabled === true && fc.maxPerCorp > VENDOR_CONTRACT_LIMIT_CHARACTER) {
    out.freeCorps.push(`contracts.maxPerCorp=${fc.maxPerCorp} > ${VENDOR_CONTRACT_LIMIT_CHARACTER} personal contract `
      + "a CEO may hold (EveJS ConTooManyContractsMax) - contracts over it fail CONTRACT_LIMIT");
  }
  return out;
}
