function restartGuardRow(name, envSuffix, type, def, min, max, origin) {
  const row = { key: `restartGuard.${name}`, type, default: def, env: `${ENV_PREFIX}RESTART_GUARD_${envSuffix}`,
    origin };
  if (type === "integer" || type === "number") Object.assign(row, { min, max, outOfRange: "clamp" });
  return row;
}

function buildInputsRow(name, envSuffix, type, def, min, max, origin) {
  const row = { key: `buildInputs.${name}`, type, default: def, env: `${ENV_PREFIX}BUILD_INPUTS_${envSuffix}`,
    origin };
  if (type === "integer" || type === "number") Object.assign(row, { min, max, outOfRange: "clamp" });
  return row;
}

function liberationRow(name, envSuffix, type, def, min, max, origin) {
  return {
    key: `liberation.${name}`, type, default: def, min, max, outOfRange: "clamp",
    env: `${ENV_PREFIX}LIBERATION_${envSuffix}`, origin,
  };
}

function standingsRow(name, envSuffix, type, def, min, max, origin) {
  return {
    key: `standings.${name}`, type, default: def, min, max, outOfRange: "clamp",
    env: `${ENV_PREFIX}STANDINGS_${envSuffix}`, origin,
  };
}

function gridRow(name, envSuffix, type, def, min, max, origin) {
  const row = { key: `grid.${name}`, type, default: def, env: `${ENV_PREFIX}GRID_${envSuffix}`,
    origin: `grid: ${origin}` };
  if (type === "integer") Object.assign(row, { min, max, outOfRange: "clamp" });
  return row;
}

function gridDefenseRow(name, envSuffix, type, def, min, max, origin, extra = {}) {
  return { ...gridRow(`defense.${name}`, `DEFENSE_${envSuffix}`, type, def, min, max, origin),
    origin: `grid: ${origin}`, ...extra };
}

function gridCrossingsRow(name, envSuffix, type, def, min, max, origin) {
  return { ...gridRow(`crossings.${name}`, `CROSSINGS_${envSuffix}`, type, def, min, max, origin),
    origin: `grid: ${origin}` };
}

