const SCHEMA_BY_ENV = new Map(SCHEMA.map((row) => [row.env, row]));
const SCHEMA_KEYS = new Set(SCHEMA.map((row) => row.key));

function deepFreeze(value) {
  if (value !== null && typeof value === "object" && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const key of Object.keys(value)) deepFreeze(value[key]);
  }
  return value;
}

function hasOwn(obj, key) {
  return obj !== null && typeof obj === "object" && Object.prototype.hasOwnProperty.call(obj, key);
}

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function getPath(obj, dotted) {
  let node = obj;
  for (const part of dotted.split(".")) {
    if (!hasOwn(node, part)) return { found: false };
    node = node[part];
  }
  return { found: true, value: node };
}

function setPath(obj, dotted, value) {
  const parts = dotted.split(".");
  let node = obj;
  for (const part of parts.slice(0, -1)) {
    if (!isPlainObject(node[part])) node[part] = {};
    node = node[part];
  }
  node[parts[parts.length - 1]] = value;
}

const TYPE_PARSERS = Object.freeze({
  boolean: {
    expected: "1, 0, true or false",
    fromString(text) {
      const lower = text.toLowerCase();
      if (lower === "1" || lower === "true") return { ok: true, value: true };
      if (lower === "0" || lower === "false") return { ok: true, value: false };
      return { ok: false };
    },
    fromJson(value) {
      return typeof value === "boolean" ? { ok: true, value } : { ok: false };
    },
  },
  integer: {
    expected: "a whole number",
    fromString(text) {
      const value = NUMBER_PATTERN.test(text) ? Number(text) : NaN;
      return Number.isInteger(value) ? { ok: true, value } : { ok: false };
    },
    fromJson(value) {
      return typeof value === "number" && Number.isInteger(value) ? { ok: true, value } : { ok: false };
    },
  },
  number: {
    expected: "a number",
    fromString(text) {
      const value = NUMBER_PATTERN.test(text) ? Number(text) : NaN;
      return Number.isFinite(value) ? { ok: true, value } : { ok: false };
    },
    fromJson(value) {
      return typeof value === "number" && Number.isFinite(value) ? { ok: true, value } : { ok: false };
    },
  },
  string: {
    expected: "a text",
    fromString(text) {
      return { ok: true, value: text };
    },
    fromJson(value) {
      return typeof value === "string" ? { ok: true, value: value.trim() } : { ok: false };
    },
  },
});

